-- EL-001 Large wire or cash withdrawal by an older adult to a new counterparty
SELECT 'EL-001' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
WHERE (a.customer_age >= 60 AND a.direction = 'out' AND a.channel IN ('wire', 'rtp', 'p2p', 'cash') AND a.counterparty_new = 1 AND a.amount_cents >= 1000000);
